// ================= PENGATURAN =================
// Semua yang perlu disesuaikan ada di blok ini saja.
const SESI = 'default';                  // nama sesi WAHA yang dipakai bot
const WAHA_URL = 'http://waha:3000';      // URL WAHA dilihat DARI n8n
const OLLAMA_URL = 'http://host.docker.internal:11434'; // URL Ollama dilihat DARI n8n
const MODEL = 'qwen2.5:7b';              // lihat `ollama list`
const FASOP_URL = 'https://fasop.example.id'; // URL FASOP dilihat DARI n8n, tanpa / di akhir

const IZINKAN_GRUP = false;   // false = bot diam di SEMUA grup (termasuk grup Early Warning)
const PREFIX_GRUP = '!bot';   // bila IZINKAN_GRUP=true, hanya pesan berawalan ini yang dijawab
const DAFTAR_IZIN = [];       // kosong = siapa pun boleh chat. Isi dengan `from` PERSIS seperti
                              // di tab Input node ini — WhatsApp kini mengirim id '...@lid',
                              // BUKAN nomor telepon, jadi nomor HP biasa tidak akan cocok.
const MAKS_RIWAYAT = 10;      // jumlah pesan (user + bot) yang diingat per chat
const RIWAYAT_KEDALUWARSA_MENIT = 60;

const SYSTEM_PROMPT = `Kamu adalah asisten WhatsApp internal Fasilitas Operasi PLN UP2B Sulawesi.
Jawab dalam Bahasa Indonesia, singkat, jelas, dan sopan. Format untuk WhatsApp:
pakai *tebal* dan daftar seperlunya, tanpa tabel markdown dan tanpa heading #.

Aturan data (WAJIB):
- Angka, status peralatan, dan nama lokasi HANYA boleh diambil dari pesan sistem
  berjudul "DATA FASOP/OPSIS". DATA itu diambil otomatis dari sistem FASOP, bukan
  diberikan oleh penanya — jangan menyebutnya "data yang Anda berikan".
- Salin angkanya persis. Jangan menjumlah, merata-rata, atau menghitung sendiri —
  pakai angka total yang sudah tersedia di DATA.
- Selalu sebutkan jam data yang tertera di DATA.
- Kalau sebuah angka bertanda [DIRAGUKAN ...], sebutkan tanda itu bersama angkanya.
- Kalau bagian DATA yang ditanyakan bertuliskan "TIDAK TERSEDIA", jawab HANYA bahwa
  datanya sedang tidak tersedia beserta alasannya. JANGAN menyimpulkan apa pun
  darinya — jangan bilang "tidak ada yang down", "normal", "aman", atau angka nol.
- Kalau pertanyaan butuh data yang tidak ada di DATA (atau tidak ada DATA sama sekali),
  katakan terus terang kamu tidak punya data itu dan sarankan membuka FASOP.
  Data yang bisa kamu berikan: beban pembangkit & frekuensi, beban KTT, beban trafo/IBT,
  status RTU & Zabbix, pemeliharaan & jadwal kunjungan, dan info peralatan.
- Angka di jawabanmu sebelumnya bisa sudah basi; selalu pakai DATA terbaru.
- Jangan memberi instruksi manuver/switching peralatan; itu wewenang dispatcher.`;
// ===============================================

const body = $json.body || {};
if (body.event !== 'message') return [];
if (body.session && body.session !== SESI) return [];

const p = body.payload || {};
if (p.fromMe) return [];                       // pesan dari nomor bot sendiri (termasuk blast)

const chatId = p.from || '';
if (!chatId || chatId === 'status@broadcast' ||
    chatId.endsWith('@broadcast') || chatId.endsWith('@newsletter')) return [];

let teks = (p.body || '').trim();
if (!teks) return [];                          // media tanpa caption, stiker, dsb.

const grup = chatId.endsWith('@g.us');
if (grup) {
  if (!IZINKAN_GRUP) return [];
  if (!teks.toLowerCase().startsWith(PREFIX_GRUP)) return [];
  teks = teks.slice(PREFIX_GRUP.length).trim();
  if (!teks) return [];
}

const pengirim = grup ? (p.participant || '') : chatId;
// Terima id lengkap ('...@lid') maupun bagian sebelum '@' saja.
if (DAFTAR_IZIN.length && !DAFTAR_IZIN.includes(pengirim) &&
    !DAFTAR_IZIN.includes(pengirim.split('@')[0])) return [];

// --- Buang pesan ganda (WAHA mengulang webhook yang dianggapnya gagal) ---
const st = $getWorkflowStaticData('global');
const sekarang = Date.now();
st.terlihat = st.terlihat || {};
for (const [k, t] of Object.entries(st.terlihat)) {
  if (sekarang - t > 10 * 60 * 1000) delete st.terlihat[k];
}
if (p.id) {
  if (st.terlihat[p.id]) return [];
  st.terlihat[p.id] = sekarang;
}

// --- Riwayat percakapan per chat ---
st.riwayat = st.riwayat || {};
const reset = ['/reset', '/baru', 'reset'].includes(teks.toLowerCase());
if (reset) delete st.riwayat[chatId];

let riwayat = st.riwayat[chatId];
if (!riwayat || sekarang - riwayat.t > RIWAYAT_KEDALUWARSA_MENIT * 60 * 1000) {
  riwayat = { t: sekarang, pesan: [] };
}

const messages = [
  { role: 'system', content: SYSTEM_PROMPT },
  ...riwayat.pesan,
  { role: 'user', content: teks },
];

// --- Topik: data mana yang perlu diambil dari FASOP ---
// Sengaja pencocokan kata, bukan tool-calling LLM: model 7B kadang lupa
// memanggil tool dan lalu mengarang angka. Kata kunci bisa salah pilih data,
// tapi tidak pernah mengarang — dan gampang ditambah di sini.
const t = ' ' + teks.toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, ' ').replace(/\s+/g, ' ') + ' ';
const kataPesan = t.trim().split(' ');
// Kata pendek harus cocok UTUH ('kit' tidak boleh cocok dengan 'kita',
// 'alat' dengan 'alamat'); kata >= 5 huruf boleh berimbuhan ('pembangkitnya').
const ada = (...kata) => kata.some(k =>
  k.includes(' ') ? t.includes(' ' + k + ' ')
  : k.length >= 5 ? kataPesan.some(w => w.startsWith(k))
  : kataPesan.includes(k));

const topik = {
  pembangkit:   ada('pembangkit', 'kit', 'pltu', 'plta', 'pltd', 'pltg', 'pltmg', 'pltmh',
                    'pltb', 'plts', 'bpp', 'unit', 'beban', 'mw', 'frekuensi', 'hz', 'sistem',
                    'opsis', 'daya', 'mvar'),
  ktt:          ada('ktt', 'konsumen', 'smelter', 'industri', 'tegangan tinggi'),
  trafo:        ada('trafo', 'ibt', 'transformator', 'gardu induk', 'distribusi'),
  monitor:      ada('rtu', 'zabbix', 'down', 'offline', 'online', 'putus', 'problem', 'telkom',
                    'voip', 'router', 'switch', 'host', 'koneksi', 'link', 'prosis', 'gangguan'),
  pemeliharaan: ada('pemeliharaan', 'maintenance', 'har', 'jadwal', 'kunjungan', 'ttd',
                    'preventive', 'preventif', 'corrective', 'korektif'),
  // 'hi' sengaja tidak ada: itu juga sapaan ("hi bot").
  peralatan:    ada('peralatan', 'perangkat', 'alat', 'device', 'merk', 'merek', 'tipe', 'type',
                    'health', 'aset', 'umur', 'cari'),
};
// Pertanyaan KTT/trafo dijawab dari datanya sendiri, tidak perlu seluruh
// daftar pembangkit — kecuali memang disebut.
if ((topik.ktt || topik.trafo) && !ada('pembangkit', 'kit', 'frekuensi', 'hz', 'sistem')) {
  topik.pembangkit = false;
}

// Kata kunci pencarian peralatan = kalimat dikurangi kata umum.
const KATA_UMUM = new Set(('apa siapa berapa bagaimana gimana kapan mana dimana apakah ' +
  'info informasi data tolong mohon cek lihat tampilkan kasih minta cari daftar ' +
  'peralatan perangkat alat device merk merek tipe type status kondisi health index hi ' +
  'umur tahun aset yang di ke dari dan atau untuk dengan pada ada saja semua ini itu ' +
  'dong ya yah nih sih kah lah punya berapa jumlah lokasi gi gardu induk site').split(' '));
const cari = kataPesan.filter(k => k.length >= 2 && !KATA_UMUM.has(k)).slice(0, 6).join(' ');
if (topik.peralatan && !cari) topik.peralatan = false;

const ping = `${FASOP_URL}/api/v1/ping/`;
const jenisTrafo = ada('ibt') ? 'ibt' : 'distribusi';
const url = {
  pembangkit:   topik.pembangkit ? `${FASOP_URL}/api/v1/opsis/beban-pembangkit/?unit=0` : ping,
  ktt:          topik.ktt ? `${FASOP_URL}/api/v1/opsis/beban-ktt/` : ping,
  trafo:        topik.trafo ? `${FASOP_URL}/api/v1/opsis/beban-trafo/?jenis=${jenisTrafo}` : ping,
  monitor:      topik.monitor ? `${FASOP_URL}/api/v1/fasop/status-monitor/` : ping,
  pemeliharaan: topik.pemeliharaan ? `${FASOP_URL}/api/v1/fasop/pemeliharaan/` : ping,
  peralatan:    topik.peralatan
                  ? `${FASOP_URL}/api/v1/fasop/peralatan/?q=${encodeURIComponent(cari)}` : ping,
};

return [{
  json: {
    session: SESI, wahaUrl: WAHA_URL, ollamaUrl: OLLAMA_URL, model: MODEL,
    maksRiwayat: MAKS_RIWAYAT,
    chatId, messageId: p.id || null, teks, reset, messages,
    topik, cari, url,
  },
}];

// Ubah balasan API FASOP jadi teks ringkas yang dibaca Ollama.
//
// Kenapa teks, bukan JSON mentah: model 7B membaca daftar "- nama: 12.3 MW"
// jauh lebih andal daripada JSON bersarang, dan teks ini jauh lebih pendek —
// konteks yang sempit membuat model mulai "lupa" isi awal data.
const awal = $('Saring & siapkan prompt').first().json;

const ambil = (nama) => {
  try { return $(nama).first().json || null; } catch (e) { return null; }
};

// 2 desimal, sama dengan kartu MW di dashboard OPSIS — kalau bot membulatkan
// berbeda, angka di WhatsApp dan di layar ruang kontrol tidak akan pernah cocok.
const angka = (v, d = 2) => (v === null || v === undefined || v === '') ? '-' : Number(v).toFixed(d);
const jam = (iso) => iso ? String(iso).replace('T', ' ').slice(0, 16) : '-';
const durasi = (m) => {
  if (m === null || m === undefined) return '-';
  if (m < 60) return `${m} menit`;
  const j = Math.floor(m / 60);
  if (j < 24) return `${j} jam ${m % 60} menit`;
  return `${Math.floor(j / 24)} hari ${j % 24} jam`;
};

// Balasan 503/4xx dari FASOP sampai ke sini sebagai { error: ... } karena node
// HTTP-nya disetel lanjut walau gagal. Pesannya diteruskan apa adanya supaya
// model menyebut ALASAN tidak tersedia, bukan menebak angka.
const tidakTersedia = (judul, r) => {
  let alasan = 'tidak ada jawaban dari FASOP';
  if (r && r.error) {
    const pesan = typeof r.error === 'string' ? r.error : (r.error.message || '');
    // n8n menanam body JSON balasan di dalam teks error, kadang ber-escape (\"message\").
    const m = pesan.match(/\\?"message\\?"\s*:\s*\\?"([^"\\]+)/);
    alasan = m ? m[1] : (pesan || alasan);
  } else if (r && r.message) {
    alasan = r.message;
  }
  return `${judul}: TIDAK TERSEDIA (${alasan})`;
};
const ok = (r) => r && r.status === 'ok' && r.dataset;

const bagian = [];

if (awal.topik.pembangkit) {
  const r = ambil('Ambil beban pembangkit');
  if (!ok(r)) bagian.push(tidakTersedia('BEBAN PEMBANGKIT', r));
  else {
    const baris = [...r.pembangkit].sort((a, b) => (b.mw || 0) - (a.mw || 0)).map(p =>
      `- ${p.nama} (${p.jenis || '-'}): ${angka(p.mw)} MW, ${angka(p.mvar)} MVAR` +
      (p.diragukan ? ` [DIRAGUKAN operator OPSIS${p.keterangan ? ': ' + p.keterangan : ''}]` : ''));
    bagian.push([
      `BEBAN PEMBANGKIT (data jam ${jam(r.waktu)})`,
      `Total beban pembangkit sistem: ${angka(r.total_mw)} MW (${r.jumlah} pembangkit)`,
      `Frekuensi sistem: ${angka(r.frekuensi_sistem, 2)} Hz`,
      ...baris,
    ].join('\n'));
  }
}

if (awal.topik.ktt) {
  const r = ambil('Ambil beban KTT');
  if (!ok(r)) bagian.push(tidakTersedia('BEBAN KTT', r));
  else {
    bagian.push([
      `BEBAN KTT / KONSUMEN TEGANGAN TINGGI (data jam ${jam(r.waktu)})`,
      `Total beban KTT: ${angka(r.total_mw)} MW (${r.jumlah} konsumen)`,
      ...r.konsumen.map(k => `- ${k.nama}: ${angka(k.mw)} MW`),
    ].join('\n'));
  }
}

if (awal.topik.trafo) {
  const r = ambil('Ambil beban trafo');
  if (!ok(r)) bagian.push(tidakTersedia('BEBAN TRAFO', r));
  else {
    const gi = [...r.gi].sort((a, b) => (b.total_mw || 0) - (a.total_mw || 0)).slice(0, 40);
    bagian.push([
      `BEBAN TRAFO ${r.jenis.toUpperCase()} (data jam ${jam(r.waktu)})`,
      `Total: ${angka(r.total_mw)} MW (${r.jumlah} trafo). Per GI:`,
      ...gi.map(g => `- ${g.site}: ${angka(g.total_mw)} MW (${g.trafo.length} trafo)`),
    ].join('\n'));
  }
}

if (awal.topik.monitor) {
  const r = ambil('Ambil status monitor');
  if (!ok(r)) bagian.push(tidakTersedia('STATUS RTU & ZABBIX', r));
  else {
    const baris = [
      `STATUS RTU & ZABBIX (data jam ${jam(r.waktu)})`,
      `RTU: ${r.rtu.jumlah} total, ${r.rtu.up} UP, ${r.rtu.down} DOWN, ${r.rtu.unknown} UNKNOWN`,
      ...r.rtu.daftar_down.slice(0, 20).map(d =>
        `- RTU DOWN: ${d.nama}${d.lokasi ? ' (' + d.lokasi + ')' : ''}, sejak ${jam(d.sejak)} (${durasi(d.durasi_menit)})`),
    ];
    if (r.rtu.down > 20) baris.push(`  (hanya 20 dari ${r.rtu.down} RTU DOWN yang dirinci)`);
    for (const z of r.zabbix) {
      baris.push(`${z.nama}: ${z.jumlah_host} host, ${z.ok} OK, ${z.problem} problem kritis, ` +
                 `${z.warning} warning, ${z.unknown} unknown (sinkron terakhir ${jam(z.sinkron_terakhir)})`);
      for (const h of z.host_bermasalah.slice(0, 15)) {
        baris.push(`- ${h.nama}${h.lokasi ? ' (' + h.lokasi + ')' : ''}: ${h.severity} — ` +
                   `${h.problem || '-'}, sejak ${jam(h.sejak)} (${durasi(h.durasi_menit)})`);
      }
    }
    bagian.push(baris.join('\n'));
  }
}

if (awal.topik.pemeliharaan) {
  const r = ambil('Ambil pemeliharaan');
  if (!ok(r)) bagian.push(tidakTersedia('PEMELIHARAAN', r));
  else {
    const rk = r.rekap_bulan;
    const baris = [
      `PEMELIHARAAN (data jam ${jam(r.waktu)}, bulan ${r.bulan})`,
      `Pemeliharaan berstatus Open saat ini: ${r.open.jumlah}`,
      ...r.open.daftar.slice(0, 15).map(m =>
        `- ${m.peralatan} (${m.jenis || '-'}) di ${m.lokasi}: ${m.tipe}, tanggal ${jam(m.tanggal).slice(0, 10)}, ` +
        `TTD ${m.sudah_ttd ? 'sudah' : 'belum'}`),
      ...(r.open.jumlah > 15 ? [`  (hanya 15 dari ${r.open.jumlah} yang dirinci)`] : []),
      `Rekap bulan ${r.bulan}: Preventive ${rk.preventive.done} selesai / ${rk.preventive.open} open; ` +
      `Corrective ${rk.corrective.done} selesai / ${rk.corrective.open} open`,
      `Jadwal kunjungan bulan ${r.bulan}: ${r.jadwal.length} lokasi`,
      ...r.jadwal.map(j =>
        `- ${j.lokasi}${j.minggu ? ' (minggu ' + j.minggu + ')' : ''}: ${j.status}, ` +
        `${j.sudah_dipelihara}/${j.jumlah_peralatan} peralatan (${j.progres_persen}%)`),
    ];
    bagian.push(baris.join('\n'));
  }
}

if (awal.topik.peralatan) {
  const r = ambil('Ambil peralatan');
  if (!ok(r)) bagian.push(tidakTersedia(`PENCARIAN PERALATAN "${awal.cari}"`, r));
  else {
    const ringkasJenis = Object.entries(r.per_jenis).map(([k, v]) => `${k} ${v}`).join(', ');
    const ringkasStatus = Object.entries(r.per_status).map(([k, v]) => `${k} ${v}`).join(', ');
    const baris = [
      `PENCARIAN PERALATAN "${r.q}" (data jam ${jam(r.waktu)})` +
        (r.cocok === 'sebagian_kata' ? ' — tidak ada yang cocok dengan semua kata, ini hasil yang cocok sebagian' : ''),
      `Ditemukan ${r.jumlah} peralatan` + (r.jumlah ? ` (${ringkasJenis}; ${ringkasStatus})` : ''),
      ...r.peralatan.map(d =>
        `- ${d.nama} | ${d.jenis || '-'} | ${d.merk || '-'} ${d.tipe || ''} | ${d.lokasi} | ` +
        `${d.status_operasi}` +
        (d.tahun_operasi ? ` | operasi ${d.tahun_operasi} (${d.umur_tahun} th)` : '') +
        (d.health_index !== undefined && d.health_index !== null
          ? ` | Health Index ${d.health_index} (${d.kategori_hi})` : '')),
    ];
    if (r.terpotong) baris.push(`  (hanya ${r.peralatan.length} dari ${r.jumlah} yang dirinci)`);
    bagian.push(baris.join('\n'));
  }
}

let messages = awal.messages;
if (bagian.length) {
  const data = 'DATA FASOP/OPSIS — satu-satunya sumber angka untuk pertanyaan terakhir. ' +
               'Jam data dalam WITA.\n\n' + bagian.join('\n\n');
  // Disisipkan tepat sebelum pertanyaan, bukan digabung ke system prompt di
  // awal: model kecil lebih memperhatikan yang dekat dengan pertanyaan. Blok
  // ini juga TIDAK disimpan ke riwayat — data basi tidak boleh terbawa ke
  // pertanyaan berikutnya.
  messages = [...awal.messages.slice(0, -1), { role: 'system', content: data },
              awal.messages[awal.messages.length - 1]];
}

return [{ json: { messages, jumlahBagian: bagian.length } }];

const awal = $('Saring & siapkan prompt').first().json;
const st = $getWorkflowStaticData('global');
st.riwayat = st.riwayat || {};

let teks;
if (awal.reset) {
  teks = 'Riwayat percakapan sudah dihapus. Silakan mulai pertanyaan baru.';
} else {
  const r = $input.first().json || {};
  let isi = (r.message && r.message.content) || '';
  // Model "thinking" (qwen3, deepseek-r1) menaruh penalarannya di <think>...</think>
  isi = isi.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

  if (r.error || !isi) {
    teks = 'Maaf, bot sedang tidak bisa menjawab. Coba lagi beberapa saat lagi.';
  } else {
    teks = isi;
    // Riwayat hanya disimpan kalau jawabannya berhasil, supaya pertanyaan yang
    // gagal tidak ikut terkirim ulang sebagai konteks di pesan berikutnya.
    // Blok DATA dari node Ringkas sengaja tidak ikut disimpan.
    const lama = st.riwayat[awal.chatId];
    const pesan = (lama && awal.messages.length > 2) ? lama.pesan : [];
    pesan.push({ role: 'user', content: awal.teks }, { role: 'assistant', content: isi });
    st.riwayat[awal.chatId] = { t: Date.now(), pesan: pesan.slice(-awal.maksRiwayat) };
  }
}

if (teks.length > 4000) teks = teks.slice(0, 4000) + '…';

const body = { session: awal.session, chatId: awal.chatId, text: teks };
if (awal.messageId) body.reply_to = awal.messageId;
return [{ json: { wahaUrl: awal.wahaUrl, body } }];
